import socket
def query(name, qtype=1, server="127.0.0.11", tcp=False):
    tid=b'\x12\x34'
    hdr=tid+b'\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00'
    q=b''.join(bytes([len(p)])+p.encode() for p in name.split('.'))+b'\x00'
    pkt=hdr+q+bytes([0,qtype>>8,qtype,0,1])
    try:
        if tcp:
            s=socket.socket(socket.AF_INET, socket.SOCK_STREAM); s.settimeout(2)
            s.connect((server,53)); s.sendall(len(pkt).to_bytes(2,'big')+pkt)
            ln=int.from_bytes(s.recv(2),'big'); data=b''
            while len(data)<ln: data+=s.recv(512)
        else:
            s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
            s.sendto(pkt,(server,53)); data,_=s.recvfrom(1024)
        rc=data[3]&0xF
        print(f"{name} qtype={qtype} {'tcp' if tcp else 'udp'} rcode={rc} an={int.from_bytes(data[6:8],'big')}")
        return data
    except Exception as e:
        print(f"{name} qtype={qtype} {'tcp' if tcp else 'udp'} ERR {e}")
    finally:
        try: s.close()
        except: pass

for n in ['commons.local','prices.internal','foo.local','bar.internal','test.internal','nope.local']:
    query(n,1); query(n,28)
query('prices.internal',1,tcp=True)
query('commons.local',1,tcp=True)
EOF"}

